// Author: MiYu. Browse local manual checkpoints with the source single-player load screen.
#include "saved_game_browser.h"
#include <algorithm>

namespace war3 {
namespace {
bool hit(GlueScreen::Rect r,float x,float y){return x>=r.x && y>=r.y && x<r.x+r.w && y<r.y+r.h;}
bool click(GlueScreen::Rect r,const UiInput& input){return input.pressed && hit(r,input.x,input.y) && hit(r,input.startX,input.startY);}
}
SavedGameBrowser::SavedGameBrowser(Archives& archives,Images& images,Renderer& renderer,Text& text,Log& log,const fs::path& dataRoot) : screen_(archives,images,renderer,text,"UI\\FrameDef\\Glue\\LoadSavedGameScreen.fdf","LoadSavedGameScreen"),renderer_(renderer),log_(log) {
    try{validateWar3UserDirectory(dataRoot);auto base=war3UserDirectory()/L"Saves",directory=base/L"Manual";auto safe=[](const fs::path& path){auto a=GetFileAttributesW(path.c_str());return a==INVALID_FILE_ATTRIBUTES || ((a&FILE_ATTRIBUTE_DIRECTORY) && !(a&FILE_ATTRIBUTE_REPARSE_POINT));};if(!safe(base) || !safe(directory))throw std::runtime_error("Invalid save directory");if(fs::exists(directory))for(const auto& item:fs::directory_iterator(directory)){auto a=GetFileAttributesW(item.path().c_str());if(a==INVALID_FILE_ATTRIBUTES || (a&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT)) || CompareStringOrdinal(item.path().extension().c_str(),-1,L".w3z",-1,TRUE)!=CSTR_EQUAL)continue;if(files_.size()>=10000)throw std::runtime_error("Too many saves");files_.push_back(item.path().stem().wstring());}std::sort(files_.begin(),files_.end(),[](const auto& a,const auto& b){return CompareStringOrdinal(a.c_str(),-1,b.c_str(),-1,TRUE)==CSTR_LESS_THAN;});}catch(const std::exception& e){files_.clear();error_="无法读取存档列表。";log_.write(std::string("saved_game_list_error=")+e.what());}screen_.focus(files_.empty()?"CancelButton":"OKButton");
}
void SavedGameBrowser::select(size_t index,size_t rows){if(index>=files_.size())return;selected_=index;if(selected_<scroll_)scroll_=selected_;if(selected_>=scroll_+rows)scroll_=selected_-rows+1;}
std::string SavedGameBrowser::selected() const {return files_.empty()?std::string{}:"Manual\\"+utf8(files_[selected_])+".w3z";}
std::string SavedGameBrowser::draw(const UiInput& input){
    auto list=screen_.bounds("FileListFrame");constexpr float step=.01875f;size_t rows=std::max(size_t(1),size_t(std::max(0.f,list.h-.008f)/step)),maximum=files_.size()>rows?files_.size()-rows:0;if(hit(list,input.x,input.y) && input.wheel)scroll_=size_t(std::clamp(std::int64_t(scroll_)-std::int64_t(input.wheel)*3,std::int64_t(0),std::int64_t(maximum)));if(!files_.empty()){if(input.key==VK_UP)select(selected_?selected_-1:0,rows);if(input.key==VK_DOWN)select(std::min(selected_+1,files_.size()-1),rows);if(input.key==VK_HOME)select(0,rows);if(input.key==VK_END)select(files_.size()-1,rows);if(input.key==VK_PRIOR)select(selected_>=rows?selected_-rows:0,rows);if(input.key==VK_NEXT)select(std::min(selected_+rows,files_.size()-1),rows);}
    bool open=false;for(size_t row=0;row<rows && scroll_+row<files_.size();++row){GlueScreen::Rect area{list.x+.004f,list.y+.004f+float(row)*step,list.w-.0245f,step};if(click(area,input)){select(scroll_+row,rows);open=input.doubleClick;break;}}std::set<std::string> enabled{"CancelButton"};if(!files_.empty())enabled.insert("OKButton");auto action=screen_.draw("LoadSavedGameScreen",input,enabled,true);screen_.backdropAt("StandardEditBoxBackdropTemplate",list);float scale=std::min(renderer_.width()/.8f,renderer_.height()/.6f),left=(renderer_.width()-.8f*scale)/2,top=(renderer_.height()-.6f*scale)/2;for(size_t row=0;row<rows && scroll_+row<files_.size();++row){auto index=scroll_+row;GlueScreen::Rect area{list.x+.004f,list.y+.004f+float(row)*step,list.w-.0245f,step};if(index==selected_)renderer_.rect(left+area.x*scale,top+area.y*scale,area.w*scale,area.h*scale,0x9f344b6b);screen_.imageAt("UI\\Widgets\\Glues\\icon-file.blp",{area.x,area.y,.01875f,.01875f});screen_.textAt("StandardInfoTextTemplate",utf8(files_[index]),{area.x+.022f,area.y,area.w-.022f,area.h},true,index==selected_,true,.013f);}auto pane=screen_.bounds("MapInfoPaneContainer");if(!files_.empty())screen_.textAt("StandardInfoTextTemplate",utf8(files_[selected_]),{pane.x,pane.y,pane.w,.03f},true,false,true,.013f);if(!error_.empty())screen_.textAt("StandardValueTextTemplate",error_,{pane.x,pane.y+.04f,pane.w,.05f},true,false,true,.011f);screen_.overlay();if(action=="CancelButton" || input.key==VK_ESCAPE)return "CancelButton";if(!files_.empty() && (action=="OKButton" || open))return "LoadSavedGame";return {};
}
}
